use serde::{Deserialize,Serialize}; use super::{decision::Decision,digest,error::{AdmissionError,AdmissionErrorKind,Result},subject::SubjectId};
#[derive(Clone,Debug,Serialize,Deserialize)] pub struct Receipt{pub id:String,pub subject:SubjectId,pub actor:String,pub decision:Decision,pub input_digest:String,pub output_digest:String,pub parent:Option<String>,pub epoch:u64,pub sequence:u64}
impl Receipt{pub fn compute_id(&self)->String{digest::digest(&[&self.subject.key(),&self.actor,self.decision.code(),&self.input_digest,&self.output_digest,self.parent.as_deref().unwrap_or(""),&self.epoch.to_string(),&self.sequence.to_string()])}pub fn seal(mut self)->Self{self.id=self.compute_id();self}pub fn validate(&self)->Result<()>{self.subject.validate()?;if self.actor.trim().is_empty()||self.input_digest.len()<8||self.output_digest.len()<8{return Err(AdmissionError::new(AdmissionErrorKind::ReceiptInvalid,"receipt.fields.invalid","actor and input/output digests required").subject(self.subject.key()))}if self.id!=self.compute_id(){return Err(AdmissionError::new(AdmissionErrorKind::ReceiptInvalid,"receipt.id.mismatch","receipt id does not match canonical fields").subject(self.subject.key()))}Ok(())}}
#[derive(Clone,Debug,Default,Serialize,Deserialize)] pub struct ReceiptChain{pub receipts:Vec<Receipt>} impl ReceiptChain{pub fn append(&mut self,r:Receipt)->Result<()>{r.validate()?;let expected=self.receipts.last().map(|x|x.id.clone());if r.parent!=expected{return Err(AdmissionError::new(AdmissionErrorKind::ReceiptInvalid,"receipt.parent.mismatch","receipt parent must equal chain head").subject(r.subject.key()))}if r.sequence!=self.receipts.len() as u64{return Err(AdmissionError::new(AdmissionErrorKind::ReceiptInvalid,"receipt.sequence.mismatch","receipt sequence must be contiguous").subject(r.subject.key()))}self.receipts.push(r);Ok(())}pub fn verify(&self)->Result<()>{let mut prev=None;for(i,r)in self.receipts.iter().enumerate(){r.validate()?;if r.parent!=prev||r.sequence!=i as u64{return Err(AdmissionError::new(AdmissionErrorKind::ReceiptInvalid,"receipt.chain.invalid","chain linkage invalid"))}prev=Some(r.id.clone());}Ok(())}pub fn head(&self)->Option<&Receipt>{self.receipts.last()}}